const p='p', q='q';
// Use a small symbolic checker via Python sympy if available through child_process is not allowed? Node has no process. We'll do manual numeric randomized validation.
function check(vals){
  const {p,q,lam,r,rt,Pt,P,qt,Q,chi,tau,mu,e}=vals;
  const a=p+q, b=p*q;
  const phi=lam-r;
  const lam_t=rt+q*r-p*lam;
  const phi_t=(q-p)*r-p*phi;
  const C=p/a;
  const dF=lam*lam_t + C*phi*phi_t;
  const diss=p*(1+p/a)*lam*lam + (b/a)*r*r;
  const rhs=(rt+a*r)*lam;
  return {spatialResidual:dF+diss-rhs};
}
let max=0;
for(let i=0;i<10000;i++){
  const vals={p:Math.random()*3,q:Math.random()*3,lam:Math.random()*2-1,r:Math.random()*2-1,rt:Math.random()*2-1};
  if(vals.p+vals.q===0) { vals.p=1; }
  const res=check(vals).spatialResidual;
  max=Math.max(max,Math.abs(res));
}
nodeRepl.write(JSON.stringify({maxSpatialResidual:max}, null, 2));

