function residual(vals){
  const {a,b,tau,P,Q,R}=vals; // Q=q, R=P_t
  const alpha=1+2*a*tau;
  const beta=a+b*tau;
  const gamma=a*a+b*(1+a*tau);
  const lhs=(R+a*P+b*Q)*(tau*R+(1+a*tau)*P+a*Q);
  const deriv=alpha*P*R + beta*(R*Q + P*P) + gamma*Q*P;
  const rhs=0.5*0; // derivative expression already no 1/2 because d(0.5*quadratic)=alpha P R+beta(RQ+P^2)+gamma QP
  const rem=tau*R*R+tau*(a*a-b)*P*P+a*b*Q*Q;
  return lhs-deriv-rem;
}
